<template>
  <div class="chat-wrapper">
    <!-- Иконка -->
    <div class="chat-header-center">
      <img src="@/assets/images/IconTower.svg" class="icon-tower" alt="Icon Tower" />
      <transition name="fade-slide">
        <span class="header-text" v-if="!isMobile">Чат из сайта FoxMage3243</span>
      </transition>
    </div>

    <!-- Чат -->
    <div class="ContainerChat">
      <transition-group name="bubble" tag="div">
        <div v-for="(msg, index) in messages" :key="msg.id" class="messageRow">
          <div class="messageBlock">
            <div class="name-bubble" :style="{ color: msg.color || '#dbd820' }">
	      <div class="avatar" v-html="msg.avatar"></div>{{ msg.username }}
            </div>
            <div class="text-bubble">
              <span v-html="msg.html"></span>
              <span class="time-inline">{{ msg.time }}</span>
            </div>
          </div>
        </div>
      </transition-group>
    </div>

    <!-- Twitch -->
    <div class="twitch-button-wrapper">
      <a href="https://www.twitch.tv/foxmage3243" target="_blank" rel="noopener noreferrer">
        <button class="twtich-popup">Twitch Channel</button>
      </a>
    </div>
  </div>
</template>

<script>
import tmi from "tmi.js";

export default {
  name: "StreamChat",
  data() {
    return {
      messages: [],
      avatarCache: {},
      isMobile: false,
      nextId: 0,
    };
  },

  mounted() {
    this.checkMobile();
    window.addEventListener("resize", this.checkMobile);

    this.startTwitchChat();
  },

  beforeUnmount() {
    window.removeEventListener("resize", this.checkMobile);
  },

  methods: {
    checkMobile() {
      this.isMobile = window.innerWidth <= 600;
    },

    scrollToBottom() {
      this.$nextTick(() => {
        const el = this.$el.querySelector(".ContainerChat");
        if (el) el.scrollTop = el.scrollHeight;
      });
    },

    startTwitchChat() {
      const client = new tmi.Client({
        connection: { reconnect: true },
        channels: ["foxmage3243"],
      });

      client.connect();

      client.on("message", async (channel, tags, message) => {
        const username = tags.username;
        const avatar = await this.getAvatar(username);

        const html = this.parseMessageWithEmotes(message, tags.emotes || {});
        const time = new Date().toLocaleTimeString("ru-RU", {
          hour: "2-digit",
          minute: "2-digit",
        });

        const id = this.nextId++;

        this.messages.push({
          id,
          username: tags["display-name"] || username,
          color: tags.color,
          html,
          avatar,
          time,
        });

        // Автоудаление через 20 секунд
        setTimeout(() => {
          const idx = this.messages.findIndex(m => m.id === id);
          if (idx !== -1) this.messages.splice(idx, 1);
        }, 50000);

        // Автоскролл вниз
        this.scrollToBottom();

        // Ограничение размера массива
        if (this.messages.length > 150) {
          this.messages.shift();
        }
      });
    },

    async getAvatar(username) {
      if (this.avatarCache[username]) return this.avatarCache[username];

      let finalUrl = "";

      try {
        const res = await fetch(`https://decapi.me/twitch/avatar/${username}`);
        finalUrl = await res.text();
      } catch (e) {
        finalUrl = "";
      }

      const html = `
        <img 
          src="${finalUrl}" 
          alt="${username}" 
          width="24 
          height="24
          style="
            border-radius: 50%;
            border: 1px solid #dbd820;
          "
        />
      `;

      this.avatarCache[username] = html;
      return html;
    },

    parseMessageWithEmotes(message, emotes) {
      if (!emotes || Object.keys(emotes).length === 0) {
        return this.escapeHtml(message);
      }

      let parts = [];
      let lastIndex = 0;
      let positions = [];

      Object.entries(emotes).forEach(([id, arr]) => {
        arr.forEach((pair) => {
          const [start, end] = pair.split("-").map(Number);
          positions.push({ id, start, end });
        });
      });

      positions.sort((a, b) => a.start - b.start);

      for (const e of positions) {
        parts.push(this.escapeHtml(message.substring(lastIndex, e.start)));

        parts.push(`
          <img 
            class="emote"
            src="https://static-cdn.jtvnw.net/emoticons/v2/${e.id}/default/dark/1.0"
          />
        `);

        lastIndex = e.end + 1;
      }

      parts.push(this.escapeHtml(message.substring(lastIndex)));

      return parts.join("");
    },

    escapeHtml(text) {
      return text.replace(/[&<>"']/g, (ch) => {
        return {
          "&": "&amp;",
          "<": "&lt;",
          ">": "&gt;",
          '"': "&quot;",
          "'": "&#039;",
        }[ch];
      });
    },
  },
};
</script>

